diff --git a/src/liblzma/lz/lz_decoder.c b/src/liblzma/lz/lz_decoder.c
index 6dc4cef..4314a06 100644
--- a/src/liblzma/lz/lz_decoder.c
+++ b/src/liblzma/lz/lz_decoder.c
@@ -277,8 +277,12 @@ lzma_lz_decoder_init(lzma_next_coder *next, const lzma_allocator *allocator,
 			= lz_options.dict_size + 2 * LZ_DICT_REPEAT_MAX;

 	// Allocate and initialize the dictionary.
+	//
+	// NOTE: If this allocation fails, the caller must clean up the
+	// whole coder with lzma_next_end(). A coder that was initialized
+	// via lzma_next_filter_init() must not be reused after a failed
+	// initialization attempt.
 	if (coder->dict.size != alloc_size) {
-		coder->dict.size = 0;
 		lzma_free(coder->dict.buf, allocator);

 		// The LZ_DICT_EXTRA bytes at the end of the buffer aren't
@@ -296,7 +300,7 @@ lzma_lz_decoder_init(lzma_next_coder *next, const lzma_allocator *allocator,
 		coder->dict.size = alloc_size;
 	}

-	lz_decoder_reset(next->coder);
+	lz_decoder_reset(coder);

 	// Use the preset dictionary if it was given to us.
 	if (lz_options.preset_dict != NULL

